  \draw (0,0.22) -- (0,-0.22);
  \node[below left] at (0,-0.05) {$B$};
  \node[above right] at (7,0) {$C$};
  \draw (5.17,0.22) -- (5.17,-0.22);
  \node[below] at (5.17,-0.25) {$X$};
  \draw (0,0) ++(5:5.17) arc (5:74:5.17);
  \draw (5.17,0) ++(103:5.17) arc (103:140:5.17);
  \draw (0,0) -- (2.59,4.48);
\end{tikzpicture}
\end{center}

